import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_3x3_bf16_forward(torch::Tensor x, torch::Tensor w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Direct 3x3, stride-1, pad-0 convolution specialized for CIN input channels.
// Cooperative tiled kernel:
//  - Each CTA computes a 32x32 output tile for CTILE output channels of one batch.
//  - The (32+2)x(32+2)xCIN input patch and CTILE*CIN*9 weights are staged in smem
//    via CUTE tensors.
//  - Each of the 256 threads produces a 2x2 micro-tile with fp32 accumulation.
template <typename T, int CIN, int CTILE>
__global__ __launch_bounds__(256)
void conv2d_3x3_s1p0_kernel(const T* __restrict__ Xp,
                            const T* __restrict__ Wp,
                            T* __restrict__ Yp,
                            int N, int H, int W,
                            int Cout, int Hout, int Wout)
{
  constexpr int TILE_H  = 32;
  constexpr int TILE_W  = 32;
  constexpr int IN_H    = TILE_H + 2;
  constexpr int IN_W    = TILE_W + 2;
  constexpr int THREADS = 256;

  const int tid    = threadIdx.x;
  const int n      = blockIdx.z;
  const int tiles_x = (Wout + TILE_W - 1) / TILE_W;
  const int tile_y = blockIdx.x / tiles_x;
  const int tile_x = blockIdx.x - tile_y * tiles_x;
  const int oh0 = tile_y * TILE_H;
  const int ow0 = tile_x * TILE_W;
  const int co0 = blockIdx.y * CTILE;

  // Global tensors described with CUTE layouts
  Tensor mX = make_tensor(make_gmem_ptr(Xp),
                          make_shape(N, Int<CIN>{}, H, W),
                          make_stride((int64_t)CIN * H * W, (int64_t)H * W, (int64_t)W, _1{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wp),
                          make_shape(Cout, Int<CIN>{}, _9{}),
                          make_stride((int64_t)CIN * 9, _9{}, _1{}));
  Tensor mY = make_tensor(make_gmem_ptr(Yp),
                          make_shape(N, Cout, Hout, Wout),
                          make_stride((int64_t)Cout * Hout * Wout, (int64_t)Hout * Wout,
                                      (int64_t)Wout, _1{}));

  // Shared tiles
  __shared__ T sX_raw[CIN * IN_H * IN_W];
  __shared__ T sW_raw[CTILE * CIN * 9];
  Tensor sX = make_tensor(make_smem_ptr(sX_raw),
                          make_shape(Int<CIN>{}, Int<IN_H>{}, Int<IN_W>{}),
                          make_stride(Int<IN_H * IN_W>{}, Int<IN_W>{}, _1{}));
  Tensor sW = make_tensor(make_smem_ptr(sW_raw),
                          make_shape(Int<CTILE>{}, Int<CIN>{}, _9{}),
                          make_stride(Int<CIN * 9>{}, _9{}, _1{}));

  // Stage the input patch cooperatively (zero-fill out-of-range rows/cols)
  for (int idx = tid; idx < CIN * IN_H * IN_W; idx += THREADS) {
    int iw = idx % IN_W;
    int t  = idx / IN_W;
    int ih = t % IN_H;
    int c  = t / IN_H;
    int h  = oh0 + ih;
    int w  = ow0 + iw;
    T v = T(0.f);
    if ((unsigned)h < (unsigned)H && (unsigned)w < (unsigned)W) {
      v = mX(n, c, h, w);
    }
    sX(c, ih, iw) = v;
  }

  // Stage the weights cooperatively
  for (int idx = tid; idx < CTILE * CIN * 9; idx += THREADS) {
    int k  = idx % 9;
    int t  = idx / 9;
    int c  = t % CIN;
    int co = t / CIN;
    T v = T(0.f);
    if (co0 + co < Cout) v = mW(co0 + co, c, k);
    sW(co, c, k) = v;
  }
  __syncthreads();

  // Each thread owns a 2x2 micro-tile of the output
  const int r0  = (tid / 16) * 2;  // local row    in [0, 32)
  const int cl0 = (tid % 16) * 2;  // local column in [0, 32)

  float acc[CTILE][2][2];
  #pragma unroll
  for (int co = 0; co < CTILE; ++co)
    #pragma unroll
    for (int dy = 0; dy < 2; ++dy)
      #pragma unroll
      for (int dx = 0; dx < 2; ++dx)
        acc[co][dy][dx] = 0.f;

  #pragma unroll
  for (int c = 0; c < CIN; ++c) {
    // Register-cache the 4x4 input window feeding the 2x2 micro-tile
    float xw[4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i)
      #pragma unroll
      for (int j = 0; j < 4; ++j)
        xw[i][j] = static_cast<float>(sX(c, r0 + i, cl0 + j));

    #pragma unroll
    for (int co = 0; co < CTILE; ++co) {
      float wr[9];
      #pragma unroll
      for (int k = 0; k < 9; ++k)
        wr[k] = static_cast<float>(sW(co, c, k));

      #pragma unroll
      for (int dy = 0; dy < 2; ++dy)
        #pragma unroll
        for (int dx = 0; dx < 2; ++dx)
          #pragma unroll
          for (int kh = 0; kh < 3; ++kh)
            #pragma unroll
            for (int kw = 0; kw < 3; ++kw)
              acc[co][dy][dx] += xw[dy + kh][dx + kw] * wr[kh * 3 + kw];
    }
  }

  // Epilogue: store with fp32 -> bf16 conversion
  #pragma unroll
  for (int co = 0; co < CTILE; ++co) {
    const int gco = co0 + co;
    if (gco >= Cout) continue;
    #pragma unroll
    for (int dy = 0; dy < 2; ++dy) {
      const int oh = oh0 + r0 + dy;
      if (oh >= Hout) continue;
      #pragma unroll
      for (int dx = 0; dx < 2; ++dx) {
        const int ow = ow0 + cl0 + dx;
        if (ow >= Wout) continue;
        mY(n, gco, oh, ow) = static_cast<T>(acc[co][dy][dx]);
      }
    }
  }
}

torch::Tensor conv2d_3x3_bf16_forward(torch::Tensor x, torch::Tensor w) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16 && w.scalar_type() == at::kBFloat16,
              "x and w must be bfloat16");
  TORCH_CHECK(x.dim() == 4 && w.dim() == 4, "x:[N,C,H,W], w:[Cout,Cin,3,3]");
  TORCH_CHECK(w.size(2) == 3 && w.size(3) == 3, "kernel size must be 3x3");

  const int64_t N    = x.size(0);
  const int64_t CIN  = x.size(1);
  const int64_t H    = x.size(2);
  const int64_t W    = x.size(3);
  const int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == CIN, "weight/input channel mismatch");
  TORCH_CHECK(CIN == 3, "this kernel is specialized for 3 input channels");

  const int64_t Hout = H - 2;  // stride=1, pad=0, k=3
  const int64_t Wout = W - 2;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid spatial sizes");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  auto y   = torch::empty({N, Cout, Hout, Wout}, x.options());

  using T = cute::bfloat16_t;
  constexpr int TILE  = 32;
  constexpr int CTILE = 16;

  dim3 block(256);
  dim3 grid((unsigned)(((Hout + TILE - 1) / TILE) * ((Wout + TILE - 1) / TILE)),
            (unsigned)((Cout + CTILE - 1) / CTILE),
            (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_3x3_s1p0_kernel<T, 3, CTILE><<<grid, block, 0, stream>>>(
      reinterpret_cast<const T*>(x_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<const T*>(w_c.data_ptr<at::BFloat16>()),
      reinterpret_cast<T*>(y.data_ptr<at::BFloat16>()),
      (int)N, (int)H, (int)W, (int)Cout, (int)Hout, (int)Wout);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_3x3_s1p0_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

conv_ext = load_inline(
    name="cute_conv2d_3x3_bf16_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_3x3_bf16_forward"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3,
                               bias=False, dtype=torch.bfloat16)
        self._ext = conv_ext

    def forward(self, x):
        if not x.is_cuda:
            return F.conv2d(x, self.conv1.weight, None, 1, 0, 1, 1)
        return self._ext.conv2d_3x3_bf16_forward(x, self.conv1.weight)

